__global__ void matrix_mul_shared_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float A_tile[16][16];
    __shared__ float B_tile[16][16];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    for (int tile = 0; tile < (N + 15) / 16; ++tile) {
        int tile_offset = tile * 16;
        int A_row = row;
        int A_col = tile_offset + threadIdx.x;
        int B_row = tile_offset + threadIdx.y;
        int B_col = col;

        if (A_row < N && A_col < N) {
            A_tile[threadIdx.y][threadIdx.x] = A[A_row * N + A_col];
        } else {
            A_tile[threadIdx.y][threadIdx.x] = 0.0f;
        }

        if (B_row < N && B_col < N) {
            B_tile[threadIdx.y][threadIdx.x] = B[B_row * N + B_col];
        } else {
            B_tile[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        for (int k = 0; k < 16; ++k) {
            sum += A_tile[threadIdx.y][k] * B_tile[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
